import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  Box,
  Typography,
  Avatar,
  CircularProgress,
  Container,
  Stack,
  Tab,
  Tabs,
  Button,
  alpha,
  tabsClasses,
} from "@mui/material";
import {
  Refresh as RefreshIcon,
  DoneAll as MarkAllIcon,
  Info as InfoIcon,
  Warning as WarningIcon,
  CheckCircle as CheckCircleIcon,
  Error as ErrorIcon,
} from "@mui/icons-material";
import { useSelector } from "react-redux";
import { toast } from "react-hot-toast";
import DataTable from "../../../components/DataTable";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const getRelativeTime = (dateString) => {
  if (!dateString) return "";
  const now = new Date();
  const date = new Date(dateString);
  const diffInSeconds = Math.floor((now - date) / 1000);

  if (diffInSeconds < 60) return "just now";
  if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
  if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
  if (diffInSeconds < 2592000) return `${Math.floor(diffInSeconds / 86400)}d ago`;
  return date.toLocaleDateString();
};


const getNotificationIcon = (type) => {
  const iconStyle = { fontSize: "1.25rem" };
  switch (type) {
    case "success":
    case "registration":
    case "subscription":
      return <CheckCircleIcon sx={{ ...iconStyle, color: "#4CC66E" }} />;
    case "warning":
    case "missed_workout":
      return <WarningIcon sx={{ ...iconStyle, color: "#FFB020" }} />;
    case "error":
    case "payment_failed":
      return <ErrorIcon sx={{ ...iconStyle, color: "#D14343" }} />;
    case "info":
    case "update":
    default:
      return <InfoIcon sx={{ ...iconStyle, color: "#3B82F6" }} />;
  }
};

const NotificationsFeed = () => {
  const [notifications, setNotifications] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState(0); // 0: All, 1: Unread
  const token = useSelector((state) => state.auth.token);

  const fetchNotifications = useCallback(async () => {
    if (!token) return;
    setIsLoading(true);
    try {
      const res = await fetch(`${BASE_URL}/notifications?tab=all&limit=100&offset=0`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message);
      setNotifications(json.data?.notifications || []);
    } catch (err) {
      console.error("Error fetching notifications:", err);
      toast.error("Failed to load notifications");
    } finally {
      setIsLoading(false);
    }
  }, [token]);

  useEffect(() => {
    fetchNotifications();
  }, [fetchNotifications]);

  const handleNotificationClick = async (notification) => {
    if (!notification.is_read) {
      // Optimistic update
      setNotifications((prev) =>
        prev.map((n) => (n.id === notification.id ? { ...n, is_read: true } : n))
      );

      try {
        const res = await fetch(`${BASE_URL}/notifications/${notification.id}/read`, {
          method: "PATCH",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });
        const json = await res.json();
        if (!res.ok || json.error) throw new Error(json.message);
      } catch (err) {
        console.error("Error marking notification as read:", err);
      }
    }
  };

  const handleMarkAllRead = async () => {
    if (notifications.every((n) => n.is_read)) return;

    const toastId = toast.loading("Marking all as read...");
    const oldNotifications = [...notifications];
    
    // Optimistic update
    setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));

    try {
      const res = await fetch(`${BASE_URL}/notifications/read-all`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message);
      toast.success("Everything marked as read", { id: toastId });
    } catch (err) {
      console.error("Error marking all read:", err);
      setNotifications(oldNotifications);
      toast.error("Failed to mark all as read", { id: toastId });
    }
  };

  const filteredNotifications = useMemo(() => {
    if (activeTab === 1) {
      return notifications.filter((n) => !n.is_read);
    }
    return notifications;
  }, [notifications, activeTab]);

  const columns = [
    {
      id: "type",
      label: "",
      align: "center",
      render: (row) => (
        <Avatar
          sx={{
            width: 40,
            height: 40,
            bgcolor: alpha("#FFF", 0.03),
            border: "1px solid rgba(255,255,255,0.08)",
          }}
        >
          {getNotificationIcon(row.type)}
        </Avatar>
      ),
    },
    {
      id: "title",
      label: "Message",
      render: (row) => (
        <Box sx={{ py: 1 }}>
          <Typography
            sx={{
              color: "#FFF",
              fontWeight: row.is_read ? 600 : 800,
              fontSize: "0.95rem",
              mb: 0.5,
            }}
          >
            {row.title}
          </Typography>
          <Typography
            variant="body2"
            sx={{
              color: row.is_read ? "rgba(255,255,255,0.4)" : "rgba(255,255,255,0.7)",
              fontSize: "0.85rem",
              lineHeight: 1.4,
              whiteSpace: "normal",
              display: "-webkit-box",
              WebkitLineClamp: 2,
              WebkitBoxOrient: "vertical",
              overflow: "hidden",
            }}
          >
            {row.body}
          </Typography>
        </Box>
      ),
    },
    {
      id: "created_at",
      label: "Received",
      align: "right",
      render: (row) => (
        <Typography sx={{ color: "rgba(255,255,255,0.4)", fontSize: "0.8rem", fontWeight: 600 }}>
          {getRelativeTime(row.created_at)}
        </Typography>
      ),
    },
  ];

  return (
    <Container maxWidth="lg" sx={{ py: { xs: 4, md: 6 } }}>
      <Box sx={{ 
        mb: 6, 
        display: "flex", 
        alignItems: "center", 
        justifyContent: "space-between", 
        flexWrap: "wrap", 
        gap: 2,
        px: { xs: 1, sm: 0 }
      }}>
        <Box sx={{ width: { xs: '100%', sm: 'auto' } }}>
          <Typography 
            variant="h4" 
            sx={{ 
              color: "#FFF", 
              fontWeight: 900, 
              mb: 1.5, 
              fontFamily: "'Montserrat', sans-serif",
              fontSize: { xs: "2rem", sm: "2.5rem" },
              letterSpacing: "-0.02em"
            }}
          >
            Notifications
          </Typography>
          <Typography sx={{ 
            color: "rgba(255,255,255,0.4)", 
            fontSize: { xs: "0.85rem", sm: "0.95rem" },
            fontWeight: 500,
            maxWidth: "600px",
            lineHeight: 1.6
          }}>
            Check your latest activity, system alerts, and messages in one place.
          </Typography>
        </Box>
        <Stack 
          direction={{ xs: "column", sm: "row" }} 
          spacing={2} 
          sx={{ 
            width: { xs: "100%", sm: "auto" },
            mt: { xs: 2, sm: 0 },
            justifyContent: "flex-end",
            alignItems: "center"
          }}
        >
          <Button
            fullWidth={true}
            variant="outlined"
            startIcon={<RefreshIcon />}
            onClick={fetchNotifications}
            disabled={isLoading}
            sx={{
              color: "#FFF",
              borderColor: "rgba(255, 255, 255, 0.15)",
              textTransform: "none",
              px: 4,
              py: 1.5,
              borderRadius: "14px",
              width: { xs: "100%", sm: "auto" },
              backdropFilter: "blur(10px)",
              "&:hover": { 
                borderColor: "#FFF",
                bgcolor: "rgba(255, 255, 255, 0.05)",
                transform: "translateY(-2px)" 
              },
              transition: "all 0.3s ease",
              fontFamily: "'Inter', sans-serif",
              fontSize: "0.9rem",
              fontWeight: 600,
              flexShrink: 0,
            }}
          >
            Refresh
          </Button>
          <Button
            fullWidth={true}
            startIcon={<MarkAllIcon />}
            onClick={handleMarkAllRead}
            disabled={isLoading || notifications.length === 0}
            variant="contained"
            sx={{
              bgcolor: "#9F6EDA",
              color: "#FFF",
              textTransform: "none",
              fontWeight: 700,
              px: { xs: 3, sm: 4 },
              py: 1.5,
              borderRadius: "14px",
              width: { xs: "100%", sm: "auto" },
              "&:hover": { 
                bgcolor: "#8A5BCA",
                boxShadow: "0 8px 20px rgba(159, 110, 218, 0.3)",
                transform: "translateY(-2px)"
              },
              transition: "all 0.3s ease",
              "&.Mui-disabled": { 
                bgcolor: "rgba(159, 110, 218, 0.15)", 
                color: "rgba(255,255,255,0.2)" 
              },
              fontFamily: "'Inter', sans-serif",
              fontSize: "0.9rem",
              flexShrink: 0,
            }}
          >
            Mark all read
          </Button>
        </Stack>
      </Box>

      <DataTable
        title="Inbox"
        columns={columns}
        data={filteredNotifications}
        isLoading={isLoading}
        onRowClick={(row) => handleNotificationClick(row)}
        filters={
          <Tabs
            value={activeTab}
            onChange={(_, newValue) => setActiveTab(newValue)}
            sx={{
              minHeight: 36,
              height: 36,
              "& .MuiTabs-indicator": { 
                backgroundColor: "#4CC66E", 
                height: 2,
                borderRadius: "2px 2px 0 0",
              },
              "& .MuiTab-root": {
                color: "rgba(255,255,255,0.4)",
                textTransform: "none",
                fontWeight: 700,
                fontSize: "0.8rem",
                minWidth: "auto",
                minHeight: 36,
                height: 36,
                px: 2,
                fontFamily: "'Inter', sans-serif",
                transition: "all 0.2s",
                "&:hover": { color: "rgba(255,255,255,0.8)" },
                "&.Mui-selected": { color: "#FFF" },
              },
            }}
          >
            <Tab 
              label={
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  All <Box sx={{ 
                    bgcolor: activeTab === 0 ? "rgba(255,255,255,0.1)" : "rgba(255,255,255,0.05)", 
                    px: 0.8, py: 0.1, borderRadius: "4px", fontSize: "0.65rem" 
                  }}>{notifications.length}</Box>
                </Box>
              } 
            />
            <Tab 
              label={
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  Unread <Box sx={{ 
                    bgcolor: activeTab === 1 ? "rgba(76, 198, 110, 0.2)" : "rgba(255,255,255,0.05)", 
                    color: activeTab === 1 ? "#4CC66E" : "inherit",
                    px: 0.8, py: 0.1, borderRadius: "4px", fontSize: "0.65rem" 
                  }}>{notifications.filter((n) => !n.is_read).length}</Box>
                </Box>
              } 
            />
          </Tabs>
        }
        getRowSx={(row) => ({
          ...(!row.is_read && {
            borderLeft: "4px solid #4CC66E",
            bgcolor: alpha("#4CC66E", 0.05) + " !important",
          }),
        })}
        emptyTitle="Inbox is empty"
        emptyMessage={
          activeTab === 0 
            ? "You're all caught up! There are no messages in your inbox." 
            : "Great job! You've read all your unread notifications."
        }
      />
    </Container>
  );
};

export default NotificationsFeed;
